var t=`0844-aloo-gobi`;var n=`world-0844`;var a=`IN`;var o=`south-asia`;var s=4;var r=37;var g={en:`Aloo Gobi`,ua:`Алу гобі`};var l={en:`Aloo Gobi is a India dish made with yellow onion, ginger-garlic paste, potato, cauliflower. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Алу гобі, страва кухні країни Індія. Основні складники: жовта цибуля, імбирно-часникова паста, картопля, цвітна капуста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,150,`g`],[`ginger-garlic-paste`,25,`g`],[`canola-oil`,40,`ml`],[`cumin-seeds`,6,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`potato`,380,`g`],[`cauliflower`,500,`g`],[`tomato`,240,`g`],[`ground-turmeric`,4,`g`],[`ground-coriander`,7,`g`],[`water`,150,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:t,id:n,country:`IN`,region:o,servings:4,minutes:37,title:g,text:l,steps:d};export{a as country,u as default,n as id,r as minutes,o as region,s as servings,t as slug,d as steps,l as text,g as title};